import{_ as e,o as r,c as t,a4 as c}from"./chunks/framework.BUqnS5H7.js";const f=JSON.parse('{"title":"生产者内部机制","description":"","frontmatter":{},"headers":[],"relativePath":"kafka/02-core/chapter-02-producer-internals.md","filePath":"kafka/02-core/chapter-02-producer-internals.md"}'),n={name:"kafka/02-core/chapter-02-producer-internals.md"};function s(d,a,l,o,p,i){return r(),t("div",null,[...a[0]||(a[0]=[c(`<h1 id="生产者内部机制" tabindex="-1" data-src-line="1" data-src-file="kafka/02-core/chapter-02-producer-internals.md">生产者内部机制 <a class="header-anchor" href="#生产者内部机制" aria-label="Permalink to &quot;生产者内部机制&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><p data-src-line="3" data-src-file="kafka/02-core/chapter-02-producer-internals.md">生产者看起来只是一个 <code>send()</code> 调用，但背后发生的事情远比你想象的复杂。消息从 Java 对象变成磁盘上的字节，中间经过了序列化、分区选择、批量聚合、网络发送四个阶段。每个阶段都有吞吐和延迟的权衡。</p></blockquote><h2 id="_1-发送流程全貌" tabindex="-1" data-src-line="5" data-src-file="kafka/02-core/chapter-02-producer-internals.md">1. 发送流程全貌 <a class="header-anchor" href="#_1-发送流程全貌" aria-label="Permalink to &quot;1. 发送流程全貌&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Producer.send(record)</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>拦截器（ProducerInterceptor）    ← 可选：添加 Header、记录日志</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>序列化器（Serializer）           ← Key/Value 从 Java 对象 → byte[]</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>分区器（Partitioner）            ← 决定消息去哪个分区</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>RecordAccumulator                ← 按分区聚合到 batch</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>Sender 线程                      ← 独立线程，从 Accumulator 取 batch 发送到 Broker</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>Broker 写入 Leader → 副本同步 → 返回 ACK</span></span></code></pre></div><p data-src-line="29" data-src-file="kafka/02-core/chapter-02-producer-internals.md">关键设计：<strong>Sender 是独立线程</strong>。<code>send()</code> 调用不会直接发网络请求——它把消息放进 RecordAccumulator 的缓冲区就返回了。真正的网络发送由 Sender 线程异步完成。这个设计让 <code>send()</code> 的延迟极低（只是内存操作），同时 Sender 可以攒批发送，提高网络效率。</p><h2 id="_2-序列化-为什么要用-schema" tabindex="-1" data-src-line="31" data-src-file="kafka/02-core/chapter-02-producer-internals.md">2. 序列化：为什么要用 Schema <a class="header-anchor" href="#_2-序列化-为什么要用-schema" aria-label="Permalink to &quot;2. 序列化：为什么要用 Schema&quot;">​</a></h2><p data-src-line="33" data-src-file="kafka/02-core/chapter-02-producer-internals.md">Kafka Broker 只认 <code>byte[]</code>。生产者发送的 Java 对象必须先序列化成字节数组。</p><p data-src-line="35" data-src-file="kafka/02-core/chapter-02-producer-internals.md">最简单的做法是 <code>StringSerializer</code>——把 JSON 字符串转成字节。但这有三个问题：</p><p data-src-line="37" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><strong>无结构校验</strong>：生产者今天写 <code>amount: 100</code>（int），明天改成 <code>amount: &quot;100&quot;</code>（string），消费者 <code>Integer.parseInt</code> 直接挂掉。Broker 不会拦。</p><p data-src-line="39" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><strong>体积浪费</strong>：JSON 每条消息都带字段名，20 个字段的消息有 40% 的字节是字段名。</p><p data-src-line="41" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><strong>无版本管理</strong>：谁改了字段？什么时候改的？没有记录。</p><p data-src-line="43" data-src-file="kafka/02-core/chapter-02-producer-internals.md">所以生产环境推荐用 Avro/Protobuf + Schema Registry。消息只带 4 字节 Schema ID，Schema 定义存在 Registry 里。详见 <a href="./chapter-06-schema-and-serialization.html">Schema 与序列化</a>。</p><h2 id="_3-分区选择-消息去哪" tabindex="-1" data-src-line="45" data-src-file="kafka/02-core/chapter-02-producer-internals.md">3. 分区选择：消息去哪 <a class="header-anchor" href="#_3-分区选择-消息去哪" aria-label="Permalink to &quot;3. 分区选择：消息去哪&quot;">​</a></h2><p data-src-line="47" data-src-file="kafka/02-core/chapter-02-producer-internals.md">分区器决定消息去哪个分区。详见 <a href="./chapter-01-partition-and-offset.html">分区与 Offset</a> §4。</p><p data-src-line="49" data-src-file="kafka/02-core/chapter-02-producer-internals.md">这里补充一个生产者特有的细节：<strong>粘性分区</strong>。</p><p data-src-line="51" data-src-file="kafka/02-core/chapter-02-producer-internals.md">Kafka 2.4 之前，无 Key 的消息默认用 RoundRobin——每条消息轮询到不同分区。问题在于：如果你发 100 条消息到 10 个分区，每条消息各自一个 batch，每个 batch 只有 1 条消息。1 个请求发 1 条消息，网络开销巨大，压缩比也极差。</p><p data-src-line="53" data-src-file="kafka/02-core/chapter-02-producer-internals.md">粘性分区的改进：同一个 batch 内的消息全部发到同一个分区，batch 满了再切换。100 条消息可能只需要 10 个 batch（每个 batch 10 条），网络请求减少 10 倍。</p><h2 id="_4-recordaccumulator-批量聚合的核心" tabindex="-1" data-src-line="55" data-src-file="kafka/02-core/chapter-02-producer-internals.md">4. RecordAccumulator：批量聚合的核心 <a class="header-anchor" href="#_4-recordaccumulator-批量聚合的核心" aria-label="Permalink to &quot;4. RecordAccumulator：批量聚合的核心&quot;">​</a></h2><p data-src-line="57" data-src-file="kafka/02-core/chapter-02-producer-internals.md">RecordAccumulator 是生产者内部的&quot;蓄水池&quot;。它为每个分区维护一个双端队列（Deque），队列中的每个元素是一个 ProducerBatch。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>消息到达 → 按分区路由 → 追加到对应分区的队列</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>队列尾部的 batch 未满 → 追加到当前 batch</span></span>
<span class="line"><span>队列尾部的 batch 已满 → 创建新 batch</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>batch 达到 batch.size 或等待超过 linger.ms → Sender 线程取出发送</span></span></code></pre></div><p data-src-line="70" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><code>batch.size</code> 和 <code>linger.ms</code> 是一对&quot;吞吐 vs 延迟&quot;的旋钮：</p><p data-src-line="72" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><strong><code>batch.size</code></strong>：batch 的字节大小上限。调大 → 单批更大、压缩比更高、网络请求更少，但首条消息等待更久。</p><p data-src-line="74" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><strong><code>linger.ms</code></strong>：batch 的等待时间上限。调大 → 等更久攒更多消息，但每条消息的发送延迟上限更高。</p><p data-src-line="76" data-src-file="kafka/02-core/chapter-02-producer-internals.md">两者是&quot;谁先到谁先发&quot;的关系：batch 满了立刻发，等够了也发。低延迟场景调小两者，高吞吐场景调大两者。</p><h3 id="缓冲区溢出" tabindex="-1" data-src-line="78" data-src-file="kafka/02-core/chapter-02-producer-internals.md">缓冲区溢出 <a class="header-anchor" href="#缓冲区溢出" aria-label="Permalink to &quot;缓冲区溢出&quot;">​</a></h3><p data-src-line="80" data-src-file="kafka/02-core/chapter-02-producer-internals.md">RecordAccumulator 有一个总大小限制（<code>buffer.memory</code>，默认 32MB）。如果生产者发送速度持续超过 Broker 接受速度，缓冲区会满。此时 <code>send()</code> 会阻塞，等待缓冲区释放。如果等待超过 <code>max.block.ms</code>，抛出 <code>TimeoutException</code>。</p><p data-src-line="82" data-src-file="kafka/02-core/chapter-02-producer-internals.md">这是 Kafka 生产者的背压机制——它不会无限占用内存，而是通过阻塞来降速。</p><h2 id="_5-压缩-在哪里压缩、怎么选算法" tabindex="-1" data-src-line="84" data-src-file="kafka/02-core/chapter-02-producer-internals.md">5. 压缩：在哪里压缩、怎么选算法 <a class="header-anchor" href="#_5-压缩-在哪里压缩、怎么选算法" aria-label="Permalink to &quot;5. 压缩：在哪里压缩、怎么选算法&quot;">​</a></h2><p data-src-line="86" data-src-file="kafka/02-core/chapter-02-producer-internals.md">压缩发生在 <strong>Sender 线程取出 batch 发送时</strong>，不是消息到达时。这意味着压缩的是整个 batch，而不是单条消息——batch 越大，压缩比越高。</p><p data-src-line="88" data-src-file="kafka/02-core/chapter-02-producer-internals.md">Kafka 支持 5 种压缩算法：</p><table tabindex="0"><thead data-src-line="90" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><tr data-src-line="90" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><th style="text-align:left;">算法</th><th style="text-align:left;">核心特点</th></tr></thead><tbody data-src-line="92" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><tr data-src-line="92" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><td style="text-align:left;">none</td><td style="text-align:left;">不压缩，最低延迟</td></tr><tr data-src-line="93" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><td style="text-align:left;">gzip</td><td style="text-align:left;">压缩比最高，但 CPU 开销大</td></tr><tr data-src-line="94" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><td style="text-align:left;">snappy</td><td style="text-align:left;">速度和压缩比均衡</td></tr><tr data-src-line="95" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><td style="text-align:left;">lz4</td><td style="text-align:left;">压缩速度最快，通用推荐</td></tr><tr data-src-line="96" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><td style="text-align:left;">zstd</td><td style="text-align:left;">压缩比接近 gzip，速度接近 lz4</td></tr></tbody></table><p data-src-line="98" data-src-file="kafka/02-core/chapter-02-producer-internals.md">选择的核心权衡是 <strong>CPU vs 带宽</strong>：</p><ul data-src-line="100" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><li data-src-line="100" data-src-file="kafka/02-core/chapter-02-producer-internals.md">带宽充裕、CPU 紧张 → 不压缩或 snappy</li><li data-src-line="101" data-src-file="kafka/02-core/chapter-02-producer-internals.md">带宽紧张、CPU 充裕 → zstd（最高压缩比）</li><li data-src-line="102" data-src-file="kafka/02-core/chapter-02-producer-internals.md">不确定 → lz4（最安全的默认选择）</li></ul><p data-src-line="104" data-src-file="kafka/02-core/chapter-02-producer-internals.md">压缩是端到端的：生产者压缩 → Broker 存储压缩数据 → 消费者解压。Broker 通常不解压，只做字节转发。所以压缩的 CPU 开销由生产者和消费者分担，Broker 不受影响。</p><p data-src-line="106" data-src-file="kafka/02-core/chapter-02-producer-internals.md">详见 <a href="./../04-performance/chapter-04-compression-tradeoff.html">压缩权衡</a>。</p><h2 id="_6-异常处理" tabindex="-1" data-src-line="108" data-src-file="kafka/02-core/chapter-02-producer-internals.md">6. 异常处理 <a class="header-anchor" href="#_6-异常处理" aria-label="Permalink to &quot;6. 异常处理&quot;">​</a></h2><p data-src-line="110" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><code>send()</code> 的回调中，异常分为两类：</p><p data-src-line="112" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><strong>可重试异常</strong>（<code>RetriableException</code>）：网络抖动、Leader 选举中、ISR 副本不足。客户端会自动重试。</p><p data-src-line="114" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><strong>不可重试异常</strong>：消息过大（<code>RecordTooLargeException</code>）、Topic 不存在（<code>InvalidTopicException</code>）、权限不足（<code>AuthorizationException</code>）。重试也没用，需要修复根本问题。</p><p data-src-line="116" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><strong><code>ProducerFencedException</code></strong>：事务被另一个同 <code>transactional.id</code> 的实例抢占。必须立刻关闭 Producer，不能重试。</p><p data-src-line="118" data-src-file="kafka/02-core/chapter-02-producer-internals.md">幂等生产者的重试不会导致重复消息，详见 <a href="./chapter-05-ack-and-idempotence.html">ACK 与幂等</a>。</p><h2 id="_7-关闭生产者" tabindex="-1" data-src-line="120" data-src-file="kafka/02-core/chapter-02-producer-internals.md">7. 关闭生产者 <a class="header-anchor" href="#_7-关闭生产者" aria-label="Permalink to &quot;7. 关闭生产者&quot;">​</a></h2><p data-src-line="122" data-src-file="kafka/02-core/chapter-02-producer-internals.md"><code>producer.close()</code> 不只是释放资源——它会等待所有未完成的 <code>send()</code> 调用完成（包括重试）。如果不调用 <code>close()</code>，正在途中的消息可能丢失。</p><p data-src-line="124" data-src-file="kafka/02-core/chapter-02-producer-internals.md">带超时的 <code>close(Duration.ofSeconds(30))</code> 在超时后强制关闭，适用于不能无限等待的场景。</p>`,44)])])}const k=e(n,[["render",s]]);export{f as __pageData,k as default};
